public class Node_siblingNodes_TriageGen1Test {

    @Test
    public void testSiblingNodes() {
        Node node = new Element("div");
        Document doc = new Document();
        doc.body().appendChild(node);
        assertEquals(node.childNodes(), node.siblingNodes());
    }

    @Test
    public void testSiblingNodes_Empty() {
        Node node = new Element("div");
        Document doc = new Document();
        assertEquals(0, node.siblingNodes().size());
    }

    @Test
    public void testSiblingNodes_NullParent() {
        Node node = new Element("div");
        assertEquals(null, node.parent());
        assertEquals(0, node.siblingNodes().size());
    }

    @Test
    public void testSiblingNodes_NullDocument() {
        Node node = new Element("div");
        node.setSiblingIndex(0);
        assertEquals(0, node.siblingNodes().size());
    }

    @Test
    public void testSiblingNodes_SiblingNode() {
        Node node = new Element("div");
        Document doc = new Document();
        Node sibling = new Element("p");
        doc.body().appendChild(node);
        doc.body().appendChild(sibling);
        assertEquals(sibling, node.siblingNodes().get(0));
    }

    @Test
    public void testSiblingNodes_MultipleSiblingNodes() {
        Node node = new Element("div");
        Document doc = new Document();
        Node sibling1 = new Element("p");
        Node sibling2 = new Element("span");
        doc.body().appendChild(node);
        doc.body().appendChild(sibling1);
        doc.body().appendChild(sibling2);
        assertEquals(sibling1, node.siblingNodes().get(0));
        assertEquals(sibling2, node.siblingNodes().get(1));
    }

    @Test
    public void testSiblingNodes_SiblingNode_Index() {
        Node node = new Element("div");
        Document doc = new Document();
        Node sibling = new Element("p");
        doc.body().appendChild(node);
        doc.body().appendChild(sibling);
        assertEquals(sibling, node.siblingNodes().get(0));
    }

    @Test
    public void testSiblingNodes_SiblingNode_Index_OutOfBounds() {
        Node node = new Element("div");
        Document doc = new Document();
        doc.body().appendChild(node);
        try {
            node.siblingNodes().get(2);
            fail("Expected IndexOutOfBoundsException");
        } catch (IndexOutOfBoundsException e) {
            // expected
        }
    }

    @Test
    public void testSiblingNodes_SiblingNode_Null() {
        Node node = new Element("div");
        Document doc = new Document();
        Node sibling = null;
        doc.body().appendChild(node);
        doc.body().appendChild(sibling);
        assertEquals(0, node.siblingNodes().size());
    }

    @Test
    public void testSiblingNodes_SiblingNode_Null_Index() {
        Node node = new Element("div");
        Document doc = new Document();
        Node sibling = null;
        doc.body().appendChild(node);
        doc.body().appendChild(sibling);
        assertEquals(0, node.siblingNodes().size());
    }

    @Test
    public void testSiblingNodes_SiblingNode_Null_Index_OutOfBounds() {
        Node node = new Element("div");
        Document doc = new Document();
        doc.body().appendChild(node);
        try {
            node.siblingNodes().get(2);
            fail("Expected IndexOutOfBoundsException");
        } catch (IndexOutOfBoundsException e) {
            // expected
        }
    }

    @Test
    public void testSiblingNodes_SiblingNode_WithAttributes() {
        Node node = new Element("div");
        Document doc = new Document();
        Node sibling = new Element("p");
        sibling.attr("id", "id");
        doc.body().appendChild(node);
        doc.body().appendChild(sibling);
        assertEquals(sibling, node.siblingNodes().get(0));
    }

    @Test
    public void testSiblingNodes_SiblingNode_WithAttributes_Index() {
        Node node = new Element("div");
        Document doc = new Document();
        Node sibling = new Element("p");
        sibling.attr("id", "id");
        doc.body().appendChild(node);
        doc.body().appendChild(sibling);
        assertEquals(sibling, node.siblingNodes().get(0));
    }

    @Test
    public void testSiblingNodes_SiblingNode_WithAttributes_Index_OutOfBounds() {
        Node node = new Element("div");
        Document doc = new Document();
        doc.body().appendChild(node);
        try {
            node.siblingNodes().get(2);
            fail("Expected IndexOutOfBoundsException");
        } catch (IndexOutOfBoundsException e) {
            // expected
        }
    }

